export const LANGUAGES = ['en','th'];
export function translate(language,key){const item=copy[key];return item?item[language==='th'?1:0]:key;}
export function translator(language){return key=>translate(language,key);}
export function formatMoney(value,language='en'){return new Intl.NumberFormat(language==='th'?'th-TH':'en-TH',{style:'currency',currency:'THB',minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(value)||0);}
export function formatNumber(value,language='en',decimals=0){return new Intl.NumberFormat(language==='th'?'th-TH':'en-GB',{maximumFractionDigits:decimals}).format(Number(value)||0);}
export function formatDate(value,language='en'){if(!value)return '';const date=new Date(value.length===10?value+'T00:00:00Z':value);return Number.isFinite(date.getTime())?new Intl.DateTimeFormat(language==='th'?'th-TH':'en-GB',{day:'numeric',month:'short',year:'numeric'}).format(date):value;}
export const translationKeys=Object.keys(copy);
